def transform(grid):
    """Fill non-boundary cells in fully enclosed regions with color 4."""
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    # The frame is the most frequent non-background color; the remaining
    # dominant color is the canvas. ARC instances use a single frame color.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    boundary = max(colors, key=lambda v: counts[v])
    # Boundary is the sparse line color (not the most common color).
    boundary = min(colors, key=lambda v: counts[v])
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == boundary or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            exterior = False
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                if y == 0 or x == 0 or y == h-1 or x == w-1:
                    exterior = True
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != boundary and (ny,nx) not in seen:
                        seen.add((ny,nx)); stack.append((ny,nx))
            if not exterior:
                for y, x in comp:
                    out[y][x] = 4
    return out
